function IdolLive3D_UIRightBtnsPanel:__init( uiMain_, panelTF_ )

    self.uiMain = uiMain_ -- Env 
    self.panelTF = panelTF_

    self.baseItem = self.panelTF:Find("baseItem") 
    CfUtils.SetActive(self.baseItem, false)


    CfUtils.SetActive(self.panelTF, false)

    ---
    self.live3DRightBtnInfoVOsMap = {} -- k:uiKey, v:vo
    for _,vo in pairs(IdolLive3D_Utils.GetLive3DRightBtnInfoVOsBySkinId( self.uiMain.cardSkinId )) do
        self.live3DRightBtnInfoVOsMap[vo.key] = vo
    end


    self.active_uiKeys = {} -- list

    --- 最多放 6 个, 一口气创建, 反正成本不大;
    self.btnNodeList = {}
    for i=1,6 do 
        local newgo = CfUtils.InstantiateGo(self.baseItem, self.panelTF.gameObject)
        CfUtils.SetActive(newgo, false)
        local scriptEnv = GetLuaBehaviour(newgo, "Game.IdolLive3D.V2.IdolLive3D_UIRightBaseBtn").Env
        scriptEnv:Init()
        table.insert( self.btnNodeList, { transform = newgo.transform, env = scriptEnv } )
    end 

    ---
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    self.events = CfUtils.EventsDecorated({
        -- 允许 客制代码 手动隐藏 本按钮:
        [IdolLive3D_States.EventSetUICustomShow] = function( uiKey_, isShow_, fadeTime_, isEffectImmediately_ )
            uiKey_ = string.lower(uiKey_)
            if isNull(self.live3DRightBtnInfoVOsMap[uiKey_]) then 
                return
            end 
            if isShow_ then 
                table.insert( self.active_uiKeys, uiKey_ )
            end 
        end,

        -- 允许 客制代码 手动置灰 本按钮:
        [IdolLive3D_States.EventSetUICustomGray] = function( uiKey_, isGray_, isEffectImmediately_ )
                -- !!! 暂时不支持这个功能
        end,
    }) 


    --CfUtils.SetActive(self.panelTF, true)

end


-- 需手动调用 Delete()
function IdolLive3D_UIRightBtnsPanel:__delete()
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
end




----------------------------------------------------------


function IdolLive3D_UIRightBtnsPanel:SetShow( isShow_ )
    CfUtils.SetActive( self.panelTF, isShow_==true )
end


function IdolLive3D_UIRightBtnsPanel:IntoNewState_Before()
    self.active_uiKeys = {}
    for _,btnNode in pairs(self.btnNodeList) do 
        btnNode.env:BindClickFunc(nil)
        CfUtils.SetActive( btnNode.transform, false )
    end 
end



function IdolLive3D_UIRightBtnsPanel:IntoNewState_After()
    -- 现在, active_uiKeys 里已经装好了需要显示的 按钮的 uiKey:
    local uiKeyNum = table.count(self.active_uiKeys)
    for i=1, uiKeyNum do
        local k = self.active_uiKeys[i]
        local vo = self.live3DRightBtnInfoVOsMap[k]
        assert( isNotNull(vo) )
        if i > 6 then 
            printError("目前的 ui 右侧按钮框架 不支持 6 个以上的按钮")
            break
        end 
        local btnNode = self.btnNodeList[i]
        btnNode.env:SetName( vo.btnName )
        btnNode.env:BindClickFunc(function()
            --printError("按下 "..tostring(vo.key))
            Events.Broadcast(IdolLive3D_States.EventVirtualSimpleTap, vo.key )
        end)
        CfUtils.SetActive( btnNode.transform, true )
    end 
    ---
    CfUtils.SetActive( self.panelTF, uiKeyNum > 0 )
end







return IdolLive3D_UIRightBtnsPanel
